NCCL_DEVICE_INLINE uint32_t docaOptFlagsFromGinOptFlags(uint32_t ginOptFlags) {
  return DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_DEFAULT |
         (!!(ginOptFlags & ncclGinOptFlagsMaySkipCreditCheck) *
          DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_SKIP_AVAILABILITY_CHECK) |
         (!!(ginOptFlags & ncclGinOptFlagsAggregateRequests) * DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_SKIP_DB_RINGING);
}

template <enum doca_gpu_dev_verbs_resource_sharing_mode resource_sharing_mode, typename Coop>

NCCL_DEVICE_INLINE static ncclResult_t flushImplModeCore(ncclGinCtx ctx, Coop coop, cuda::memory_order ord,
                                                         uint32_t* abortFlag, uint64_t timeoutCycles) {
  (void)timeoutCycles; // referenced only when HasTimeout is true
  using nccl::utility::loadConst;
  using nccl::utility::testAbort;

  ncclGinGdakiGPUContext* gdaki = &((struct ncclGinGdakiGPUContext*)ctx.handle)[ctx.contextId];
  doca_gpu_dev_verbs_qp* qps = loadConst(&gdaki->gdqp);
  uint32_t steps = 0;
  uint64_t startCycle = 0;
  (void)startCycle; // referenced only when HasTimeout is true
  if NCCL_IF_CONSTEXPR (HasTimeout) startCycle = clock64();

  NVCC_PRAGMA_UNROLL_DISABLED
  for (int peer = coop.thread_rank(); peer < ctx.nRanks; peer += coop.size()) {
    uint64_t ticket = doca_gpu_dev_verbs_atomic_read<uint64_t, resource_sharing_mode>(&qps[peer].sq_rsvd_index);
    if (ticket == 0) continue; // No need to poll if there are no outstanding operations
    --ticket;

    // doca_gpu_dev_verbs_wait blocks indefinitely; only usable when there's
    // no deadline AND no abort flag to honor.
    if NCCL_IF_CONSTEXPR (!HasTimeout) {
      if (abortFlag == nullptr) {
        doca_gpu_dev_verbs_wait<resource_sharing_mode>(&qps[peer], ticket);
        continue;
      }
    }

    NVCC_PRAGMA_UNROLL_DISABLED
    while (true) {
      int status = doca_gpu_dev_verbs_poll_one_cq_at<resource_sharing_mode>(&qps[peer], ticket);
      if (status == 0) break;
      if NCCL_IF_CONSTEXPR (HasTimeout) {
        if (clock64() - startCycle >= timeoutCycles) return ncclTimeout;
      }
      if (testAbort(abortFlag, steps)) {
        if NCCL_IF_CONSTEXPR (HasTimeout) {
          cuda::atomic_thread_fence(ord, cuda::thread_scope_system);
          return ncclSuccess;
        } else break; // Original non-timeout path advances to the next peer on abort.
      }
    }
  }
  cuda::atomic_thread_fence(ord, cuda::thread_scope_system);
  return ncclSuccess;
}

__device__ static inline void doca_gpu_dev_verbs_submit_db_no_dbr(
    struct doca_gpu_dev_verbs_qp *qp, uint64_t prod_index,
    uint32_t code_opt = DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_DEFAULT) {
    if (!(code_opt & DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_SKIP_DB_RINGING)) {
        uint64_t old_prod_index =
            doca_gpu_dev_verbs_atomic_max<uint64_t, resource_sharing_mode, true>(&qp->sq_wqe_pi,
                                                                                 prod_index);
        if (old_prod_index < prod_index)
            doca_gpu_dev_verbs_ring_db<sync_scope>(qp, prod_index, code_opt);
    }
}

/**
 * @brief Submit a work request to the NIC using the DB protocol.
 *
 * @param qp - Queue Pair (QP)
 * @param prod_index - Producer index
 */
template <enum doca_gpu_dev_verbs_resource_sharing_mode resource_sharing_mode =
              DOCA_GPUNETIO_VERBS_RESOURCE_SHARING_MODE_GPU,
          enum doca_gpu_dev_verbs_sync_scope sync_scope = DOCA_GPUNETIO_VERBS_SYNC_SCOPE_GPU,
          enum doca_gpu_dev_verbs_qp_type qp_type = DOCA_GPUNETIO_VERBS_QP_SQ>
__device__ static __forceinline__ void doca_gpu_dev_verbs_submit_db(
    struct doca_gpu_dev_verbs_qp *qp, uint64_t prod_index,
    uint32_t code_opt = DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_DEFAULT) {
    if (!(code_opt & DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_SKIP_DB_RINGING)) {
        doca_gpu_dev_verbs_lock<resource_sharing_mode>(&qp->sq_lock);

        uint64_t old_prod_index =
            doca_gpu_dev_verbs_atomic_max<uint64_t, resource_sharing_mode, true>(&qp->sq_wqe_pi,
                                                                                 prod_index);
        if (old_prod_index < prod_index) {
            // Early rining of the DB to push WQEs to the NIC ASAP.
            doca_gpu_dev_verbs_ring_db<sync_scope>(qp, prod_index, code_opt);

            // In case the recovery path is triggered, the later DB ringing will cover for
            // correctness.
            doca_priv_gpu_dev_verbs_update_dbr<qp_type>(qp, prod_index);

            // Use at least either GPU or Sys synchronization scope for the second DB ringing.
            constexpr enum doca_gpu_dev_verbs_sync_scope second_db_sync_scope =
                (sync_scope <= DOCA_GPUNETIO_VERBS_SYNC_SCOPE_GPU)
                    ? sync_scope
                    : DOCA_GPUNETIO_VERBS_SYNC_SCOPE_GPU;
            doca_gpu_dev_verbs_ring_db<second_db_sync_scope>(qp, prod_index, code_opt);
        }

        doca_gpu_dev_verbs_unlock<resource_sharing_mode>(&qp->sq_lock);
    }
}

/**
 * @brief Submit a work request to the NIC using the BlueFlame protocol.
 * This function requires a single thread. Users must pass a pointer to a WQE stored in shared
 * memory. Hopper or a newer generation is required to leaverage the BlueFlame protocol.
 *
 * @param qp - Queue Pair (QP)
 * @param prod_index - Producer index
 * @param smem_wqe - WQE to be submitted directly to the NIC. The buffer must be in shared memory.

template <typename T,
          enum doca_gpu_dev_verbs_resource_sharing_mode resource_sharing_mode =
              DOCA_GPUNETIO_VERBS_RESOURCE_SHARING_MODE_GPU,
          enum doca_gpu_dev_verbs_nic_handler nic_handler = DOCA_GPUNETIO_VERBS_NIC_HANDLER_AUTO,
          enum doca_gpu_dev_verbs_cq_type cq_type = DOCA_GPUNETIO_VERBS_CQ_UNKNOWN>
__device__ static __forceinline__ void doca_gpu_dev_verbs_p_thread(
    struct doca_gpu_dev_verbs_qp *qp, struct doca_gpu_dev_verbs_addr raddr, T value,
    doca_gpu_dev_verbs_ticket_t *out_ticket,
    uint32_t code_opt = DOCA_GPUNETIO_VERBS_GPU_CODE_OPT_DEFAULT) {
    uint64_t wqe_idx;
    struct doca_gpu_dev_verbs_wqe *wqe_ptr;

    DOCA_GPUNETIO_VERBS_ASSERT(out_ticket != NULL);
    DOCA_GPUNETIO_VERBS_ASSERT(qp != NULL);
    // DOCA_GPUNETIO_VERBS_ASSERT(qp->mem_type == DOCA_GPUNETIO_VERBS_MEM_TYPE_GPU);

    wqe_idx = doca_gpu_dev_verbs_reserve_wq_slots<resource_sharing_mode, DOCA_GPUNETIO_VERBS_QP_SQ,
                                                  cq_type>(qp, 1, code_opt);
    wqe_ptr = doca_gpu_dev_verbs_get_wqe_ptr(qp, wqe_idx);

    doca_gpu_dev_verbs_prepare_inl_rdma_write_wqe_header(
        qp, wqe_ptr, wqe_idx,
        doca_gpu_dev_verbs_get_ctrl_flags<DOCA_GPUNETIO_VERBS_QP_SQ, cq_type>(qp, code_opt),
        raddr.addr, raddr.key, sizeof(T));
    doca_gpu_dev_verbs_prepare_inl_rdma_write_wqe_data<T>(qp, wqe_ptr, value);
    doca_gpu_dev_verbs_mark_wqes_ready<resource_sharing_mode>(qp, wqe_idx, wqe_idx);

    // mark_wqes_ready has already called fence.release with sufficiently strong scope. No need to
    // call it again in submit.
    constexpr enum doca_gpu_dev_verbs_sync_scope submit_sync_scope =
        (resource_sharing_mode == DOCA_GPUNETIO_VERBS_RESOURCE_SHARING_MODE_GPU)
            ? DOCA_GPUNETIO_VERBS_SYNC_SCOPE_THREAD
            : DOCA_GPUNETIO_VERBS_SYNC_SCOPE_GPU;
    doca_gpu_dev_verbs_submit<resource_sharing_mode, submit_sync_scope, nic_handler>(
        qp, wqe_idx + 1, code_opt);

    *out_ticket = wqe_idx;
}

